// Generated by scripts/sync-engine.mjs from src/engine/types.ts. Do not edit here.
// Core domain types for the Parchi order engine.
// The engine is pure TypeScript with no DOM or network access, so the same
// code runs in the browser, in a Supabase Edge Function (Deno) and in tests.

export type BillUnit = 'pc' | 'pkt' | 'box' | 'set' | 'roll' | 'pair';
export type OrderUnit = BillUnit | 'dozen' | 'carton' | 'gross';
export type TaxRate = 0 | 5 | 10 | 15 | 20;

export interface Product {
  sku: string;
  name: string;
  category: 'Stationery' | 'Gifts' | 'Baby' | 'Hardware' | 'Electronics' | 'Home';
  unit: BillUnit;            // the unit the rate is quoted in
  box?: number;              // billing units in one box
  carton?: number;           // billing units in one carton / peti
  pkt?: number;              // pieces in one packet (when unit is pc)
  rate: number;              // wholesale rate per billing unit, before tax, in US dollars
  hs: string;                // Harmonized System code
  tax: TaxRate;              // sales tax / VAT rate in %
  stock: number;             // in billing units
  reorderAt: number;
  leadDays: number;          // supplier lead time in days
  aliases: string[];         // trade names, Hindi / Tamil words, common misspellings
  specs?: string[];          // e.g. "24/6", "9w", "6x8", "250ml"
  color?: string;
  size?: 'small' | 'medium' | 'large';
}

export interface Party {
  id: string;
  name: string;
  contact: string;
  phone: string;
  area: string;
  city: string;
  country: string;
  taxId?: string;
  export: boolean;           // cross-border sale: zero-rated
  discountPct: number;
  creditDays: number;
}

export interface Span { start: number; end: number }

export type TokenKind = 'word' | 'number' | 'sep';

export interface Token {
  raw: string;
  low: string;     // lower-cased, digits normalised to ASCII
  fold: string;    // phonetic fold used for fuzzy matching
  kind: TokenKind;
  start: number;
  end: number;
}

export interface ExtractedLine {
  raw: string;
  span: Span;
  qty: number;
  qtyAssumed: boolean;
  unit?: OrderUnit;
  itemText: string;
  itemTokens: string[];      // folded tokens used for matching
  specs: string[];           // normalised specs found in the line
  color?: string;
  size?: 'small' | 'medium' | 'large';
  highlights: { span: Span; role: 'qty' | 'unit' | 'item' | 'attr' }[];
}

export interface Candidate {
  sku: string;
  score: number;
  reasons: string[];
}

export type LineStatus = 'matched' | 'review' | 'unmatched';

export interface OrderLine extends ExtractedLine {
  id: string;
  candidates: Candidate[];
  sku?: string;
  confidence: number;
  status: LineStatus;
  billQty: number;
  unitNote?: string;
  resolvedBy: 'rules' | 'history' | 'ai' | 'trader';
  why?: string;              // model's reason when resolved by AI
}

export interface Deadline {
  label: string;
  date?: string;   // ISO date
  urgent: boolean;
  span?: Span;
}

export interface ParsedOrder {
  messageText: string;
  lines: OrderLine[];
  deadline?: Deadline;
  repeatHint: boolean;
  languages: string[];
  stats: { ms: number; auto: number; review: number; unmatched: number };
}

export interface InvoiceLine {
  sku: string;
  name: string;
  hs: string;
  qty: number;
  unit: BillUnit;
  rate: number;
  discountPct: number;
  taxable: number;
  taxRate: TaxRate;
  tax: number;
  total: number;
}

export interface Invoice {
  number: string;
  date: string;
  party: Party;
  currency: string;
  export: boolean;
  lines: InvoiceLine[];
  taxSummary: { rate: TaxRate; taxable: number; tax: number }[];
  taxable: number;
  tax: number;
  roundOff: number;
  grandTotal: number;
  amountInWords: string;
  dueDate: string;
}
